function openEditor(index){editorOriginal=structuredClone(displayResults[index]);editing=editorOriginal.items.map(item=>({...item,quality:item.quality??currentCfg.quality,level:item.level??currentCfg.level,rarity:item.rarity??3}));editorRows();updateEditor();$('editDialog').showModal();}function editorRows(){$('editRows').innerHTML=editing.map((item,i)=>{const a=data.artefact.find(a=>a.id===item.id),tier=tiers[item.rarity];return`<div class="editRow"><div>${itemImage(a.id,'inventoryImage')}<b>${esc(a.name)}</b><small id="slotPrice${i}"></small></div><div><label for="tier${i}">Rarity</label><select id="tier${i}" data-slot="${i}" data-field="rarity">${tiers.filter(t=>t.available!==false).map(t=>`<option value="${t.id}" ${item.rarity===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div><label for="slotQuality${i}">Quality %</label><input id="slotQuality${i}" type="number" min="${tier.min}" max="${tier.max}" step="0.01" required value="${item.quality}" data-slot="${i}" data-field="quality"></div><div><label for="slotLevel${i}">Upgrade</label><select id="slotLevel${i}" data-slot="${i}" data-field="level">${Array.from({length:16},(_,l)=>`<option value="${l}" ${item.level===l?'selected':''}>+${l}</option>`).join('')}</select></div></div>`;}).join('');}
function editEvaluationCfg(){return {...currentCfg,market,ownedInventory:currentCfg.omitOwned===false?[]:ownedInventory};}
function updateEditor(){if(!editing)return;const inputs=[...$('editRows').querySelectorAll('input')];if(inputs.some(x=>!x.checkValidity())){$('editSummary').textContent='Enter a quality within the selected rarity range.';$('saveEdit').disabled=true;return;}try{const r=evaluateEditedBuild(editing,editEvaluationCfg(),data),cost=costForBuild(editing),originalCost=costForBuild(editorOriginal.items);$('saveEdit').disabled=!r.safe||!r.matches;$('editSummary').innerHTML=`<div class="editVerdict ${r.safe?'':'invalid'}">${r.safe?'✓ Within infection limits':'⚠ Exceeds infection limits · cannot save as a safe build'} · ${r.matches?'Matches every stat filter':r.misses.length+' stat filter(s) missed'}</div><div class="metrics">${filterStats.map(st=>metric(r,st)).join('')}<div class="metric"><b>${money(cost.purchaseComplete?cost.purchaseTotal:cost.knownPurchaseSubtotal)}</b><span>${cost.purchaseComplete?'LEFT TO BUY':'KNOWN PURCHASE SUBTOTAL'}</span><small class="target">${cost.ownedSlots} owned · ${cost.purchaseCovered} / ${cost.purchaseNeeded} needed slots priced${cost.purchaseComplete&&originalCost.purchaseComplete?'<br>Change: '+money(cost.purchaseTotal-originalCost.purchaseTotal):''}</small></div></div>${r.misses.length?'<div class="misses">'+r.misses.map(m=>{const st=filterStats.find(s=>s.key===m.key);if(m.value==null)return esc(st.name)+': price unavailable';return esc(st.name)+': '+f(m.value)+st.unit+' · '+f(m.gap)+st.unit+' '+(m.min!=null&&m.value<m.min?'below minimum':'above maximum');}).join('<br>')+'</div>':''}<div class="infectionBalance">${infections.map((k,j)=>{const cap=j<4?10:j===4?20:0;return`<span class="${(r.s[k]||0)>cap?'overLimit':''}">${esc(data.names[k])}<b>${f(r.s[k],3)} / ${cap}</b></span>`;}).join('')}</div>`;for(let i=0;i<editing.length;i++)$('slotPrice'+i).textContent=quoteLabel(cost.quotes[i]);}catch(e){$('editSummary').textContent=e.message;$('saveEdit').disabled=true;}}
$('editRows').addEventListener('input',e=>{if(e.target.dataset.field!=='quality')return;editing[+e.target.dataset.slot].quality=Number(e.target.value);updateEditor();});$('editRows').addEventListener('change',e=>{const i=+e.target.dataset.slot,k=e.target.dataset.field;if(!k)return;editing[i][k]=Number(e.target.value);if(k==='rarity'){const tier=tiers[editing[i].rarity];editing[i].quality=(tier.min+tier.max)/2;editorRows();}if(k==='level'){const a=data.artefact.find(a=>a.id===editing[i].id),count=Math.floor(editing[i].level/5)+(a.exbo==='9n7z'&&editing[i].level>=1?1:0),keys=a.exbo==='9n7z'?currentCfg.rubikKeys:a.bonus.map(b=>b.k);editing[i].bonusKeys=keys.slice(0,count);}updateEditor();});$('closeEdit').onclick=()=>$('editDialog').close();$('cancelEdit').onclick=()=>$('editDialog').close();$('resetEdit').onclick=()=>{editing=editorOriginal.items.map(item=>({...item,quality:item.quality??currentCfg.quality,level:item.level??currentCfg.level,rarity:item.rarity??3}));editorRows();updateEditor();};$('saveEdit').onclick=()=>{if(!editing)return;updateEditor();if($('saveEdit').disabled)return;try{const r=evaluateEditedBuild(editing,editEvaluationCfg(),data);if(!r.safe||!r.matches){updateEditor();return;}r.edited=true;r.tokens=r.items.map(i=>i.id+':'+i.rarity+':'+i.quality+':'+i.level);results.unshift(structuredClone(r));let persisted=true;try{localStorage.setItem('stalzone-edits-v4',JSON.stringify({cfg:currentCfg,builds:results.filter(b=>b.edited)}));}catch{persisted=false;}render();$('editDialog').close();$('progress').textContent=persisted?'Saved. Look for “Edited variation” in the results.':'Edited variation added to results. Browser storage is unavailable; this edit will not survive a reload.';}catch(e){$('editSummary').textContent='Could not save this variation: '+e.message;}};

const auctionBase=()=>location.protocol==='file:'?'http://127.0.0.1:4180':location.origin;
function rememberMarket(){try{localStorage.setItem('stalzone-market-'+marketRegion,JSON.stringify(market));}catch{}}
async function loadRegionalPrices(){const region=marketRegion;try{const response=await fetch(auctionBase()+'/api/prices?region='+region,{signal:AbortSignal.timeout(5000)});if(!response.ok)throw Error('Price service unavailable');const body=await response.json();if(region!==marketRegion)return;marketCollectionState=body.collection||null;market=mergeMarketSnapshots(body.market,marketRegion==='NA'?mergeMarketSnapshots(market,embeddedNAMarket):market);rememberMarket();cache.clear();marketStatus();}catch{marketStatus();$('refreshPrices').title='Offline snapshot; start the local auction service for updates.';}}
async function refreshMarket(){return loadRegionalPrices();}
$('refreshPrices').onclick=()=>refreshMarket(false,true);
$('marketRegion').onchange=()=>{marketRegion=$('marketRegion').value;marketCollectionState=null;try{localStorage.setItem('stalzone-market-region',marketRegion);}catch{}let snapshot=null;try{snapshot=JSON.parse(localStorage.getItem('stalzone-market-'+marketRegion));}catch{}market=mergeMarketSnapshots(snapshot?.region===marketRegion?snapshot:null,marketRegion==='NA'?embeddedNAMarket:{region:marketRegion,items:{}});cache.clear();marketStatus();dirty();loadRegionalPrices().then(()=>{if($('autoPrices').checked)refreshMarket(true);});};
$('autoPrices').onchange=()=>{try{localStorage.setItem('stalzone-auto-prices',String($('autoPrices').checked));}catch{}if($('autoPrices').checked)refreshMarket(true);};
const embeddedNAMarket=structuredClone(market);embeddedNAMarket.region='NA';
try{const region=localStorage.getItem('stalzone-market-region');if(['NA','EU','SEA','RU'].includes(region)){marketRegion=region;$('marketRegion').value=region;} $('autoPrices').checked=localStorage.getItem('stalzone-auto-prices')!=='false';const snapshot=JSON.parse(localStorage.getItem('stalzone-market-'+marketRegion)||'null');market=mergeMarketSnapshots(snapshot?.region===marketRegion?snapshot:null,marketRegion==='NA'?embeddedNAMarket:{region:marketRegion,items:{}});}catch{}
cache.clear();marketStatus();if(currentCfg&&currentCfg.marketRegion!==marketRegion)dirty();
loadRegionalPrices().then(()=>{if($('autoPrices').checked)refreshMarket(true);});
setInterval(()=>{if(!document.hidden)loadRegionalPrices();},60000);


function restoreEdits(base){try{const saved=JSON.parse(localStorage.getItem("stalzone-edits-v4")||"null");if(saved&&JSON.stringify(saved.cfg)===JSON.stringify(currentCfg)){const edits=saved.builds.map(b=>({...evaluateEditedBuild(b.items,editEvaluationCfg(),data),edited:true})).filter(b=>b.safe&&b.matches);return[...edits,...base.filter(b=>!b.edited)];}}catch{}return base.filter(b=>!b.edited);}

$("artifactToExclude").onchange=()=>{$("excludeSelected").disabled=!$("artifactToExclude").value;};$("excludeSelected").onclick=()=>excludeArtifact($("artifactToExclude").value);

function loadOwned(){try{const saved=JSON.parse(localStorage.getItem('stalzone-owned-v1')||'[]');if(Array.isArray(saved))ownedInventory=saved.filter(o=>data.artefact.some(a=>a.id===o.id)&&Number.isInteger(o.rarity)&&o.rarity>=0&&o.rarity<=6&&Number.isInteger(o.level)&&o.level>=0&&o.level<=15&&Number.isInteger(o.quantity)&&o.quantity>0);}catch{}options($('ownedArtifact'),data.artefact.slice().sort((a,b)=>a.name.localeCompare(b.name)),data.artefact[0].id);options($('ownedRarity'),tiers.filter(t=>t.available!==false).map(t=>({id:String(t.id),name:t.name})),'3');$('ownedLevel').innerHTML=Array.from({length:16},(_,i)=>`<option value="${i}" ${i===15?'selected':''}>+${i}</option>`).join('');ownedQualityBounds();renderOwned();}
function ownedQualityBounds(){const t=tiers[+$('ownedRarity').value];$('ownedQuality').min=t.min;$('ownedQuality').max=t.max;$('ownedQuality').value=(t.min+t.max)/2;}
function renderOwned(){const total=ownedInventory.reduce((s,o)=>s+o.quantity,0);$('ownedTab').textContent='Storage';$('ownedArtifactsTab').textContent='Artifacts ('+total+')';$('ownedList').innerHTML=ownedInventory.length?orderedArtifactEntries(ownedInventory).map(({item:o,index:i})=>{const a=data.artefact.find(a=>a.id===o.id),t=tiers[o.rarity];return`<div class="ownedRow"><div class="storageItemHeading"><b class="ownedItemName">${itemImage(a.id,'inventoryImage')}${esc(a.name)}</b><span class="rarityBadge" style="color:${t.color};border-color:${t.color}">${esc(t.name)}</span><span class="storageLevel">+${o.level}</span></div><div class="storageQuality"><label for="ownedQuality${i}">Exact quality %</label><input id="ownedQuality${i}" type="number" min="${t.min}" max="${t.max}" step="0.01" value="${o.quality??''}" placeholder="Blank = ${t.max}%" data-owned-quality="${i}" aria-label="Exact quality of ${esc(a.name)}"></div><div class="storageQuantity"><label for="ownedQty${i}">Quantity</label><input id="ownedQty${i}" type="number" min="1" max="9999" step="1" value="${o.quantity}" data-owned-qty="${i}" aria-label="Copies owned of ${esc(a.name)} ${esc(t.name)} +${o.level}"></div><details><summary>Bonus properties</summary>${a.bonus.map(b=>`<label class="checkrow"><input type="checkbox" data-owned-bonus="${i}" value="${b.k}" ${(o.bonusKeys||a.bonus.slice(0,Math.floor(o.level/5)+(a.exbo==='9n7z'&&o.level>=1?1:0)).map(b=>b.k)).includes(b.k)?'checked':''}>${esc(data.names[b.k])}</label>`).join('')}</details><button class="copy" data-remove-owned="${i}">Remove</button></div>`;}).join(''):'<div class="empty">No artifacts in Storage yet.</div>';$('ownedStatus').textContent='';}
function saveOwned(){collectionChanged();persistCollection('stalzone-owned-v1',ownedInventory);renderOwned();if(currentCfg){render();updateEditor();dirty();}}
function addOwned(id,rarity,level,quantity,quality=(tiers[rarity].min+tiers[rarity].max)/2){const existing=ownedInventory.find(o=>o.id===id&&o.rarity===rarity&&o.level===level&&o.quality===quality);if(existing)existing.quantity+=quantity;else ownedInventory.push({id,rarity,level,quantity,quality});saveOwned();}
$('addOwned').onclick=()=>{if(!$('ownedQuantity').reportValidity()||!$('ownedQuality').reportValidity())return;addOwned($('ownedArtifact').value,+$('ownedRarity').value,+$('ownedLevel').value,+$('ownedQuantity').value,$('ownedQuality').value===''?null:+$('ownedQuality').value);};$('ownedList').addEventListener('click',e=>{const b=e.target.closest('[data-remove-owned]');if(!b)return;ownedInventory.splice(+b.dataset.removeOwned,1);saveOwned();});$('ownedList').addEventListener('change',e=>{if(e.target.dataset.ownedBonus!==undefined){const index=+e.target.dataset.ownedBonus,o=ownedInventory[index],a=data.artefact.find(a=>a.id===o.id),limit=Math.floor(o.level/5)+(a.exbo==='9n7z'&&o.level>=1?1:0),keys=[...$('ownedList').querySelectorAll('[data-owned-bonus="'+index+'"]:checked')].map(el=>el.value);if(keys.length>limit){e.target.checked=false;$('ownedStatus').textContent='This upgrade allows '+limit+' bonus properties.';return;}o.bonusKeys=keys;saveOwned();return;}const qualityIndex=e.target.dataset.ownedQuality;if(qualityIndex!==undefined){if(!e.target.reportValidity())return;ownedInventory[+qualityIndex].quality=e.target.value===''?null:+e.target.value;saveOwned();return;}const i=e.target.dataset.ownedQty;if(i===undefined)return;if(!e.target.reportValidity())return;ownedInventory[+i].quantity=+e.target.value;saveOwned();});for(const id of ['buildTab','ownedTab'])$(id).onclick=()=>{const isOwned=id==='ownedTab';$('buildPanel').hidden=isOwned;$('ownedPanel').hidden=!isOwned;$('buildTab').setAttribute('aria-selected',String(!isOwned));$('ownedTab').setAttribute('aria-selected',String(isOwned));};

$("excludedChips").addEventListener("change",e=>{const id=e.target.dataset.rarityPreset;if(id){if(e.target.value==="custom")return;if(e.target.value==="none")delete rarityExclusions[id];else rarityExclusions[id]=tiers.filter(t=>e.target.value==="all"||t.id>=+e.target.value).map(t=>t.id);exclusionChanged();return;}const art=e.target.dataset.ruleId;if(!art)return;const tier=+e.target.dataset.ruleTier,rule=new Set(rarityExclusions[art]||[]);if(e.target.checked)rule.add(tier);else rule.delete(tier);if(rule.size)rarityExclusions[art]=[...rule].sort();else delete rarityExclusions[art];exclusionChanged();});

$("resultOrder").onchange=()=>{try{localStorage.setItem("stalzone-results-order",$("resultOrder").value);}catch{}if(currentCfg)render();};try{const order=localStorage.getItem("stalzone-results-order");if(["recommended","ehp","health_bonus","heal_efficiency","full_cost","left_to_buy","quality_high","quality_low"].includes(order))$("resultOrder").value=order;}catch{}

$("ownedRarity").onchange=ownedQualityBounds;

function recommendationNote(r){if(r.statsOnly)return '<div class="valueReason"><b>'+(r.bucketCoverage?'Recommended using +0 price buckets.':'Rarity fallback: +0 price buckets unavailable.')+'</b></div>';return `<div class="valueReason"><b>${r.build.s.cost===0?"Meets your targets with no artifact purchases needed.":r.premium<=0?"Best useful stats at the lowest estimated purchase cost.":money(r.premium)+" above the cheapest match for "+f(r.performanceGain*100,1)+"% more priority-weighted performance."}</b></div>`;}

function createSearchWorker(){return new Worker('./worker.js',{type:'module'});}
let ownedEquipment={armors:[],containers:[]},savedBuilds=[],savedDraft=null,accountWorker=null,accountResults=null,accountRunningKey=null,accountResultKey=null;
function persistCollection(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageFailure();return false;}}
function selectWorkspace(name){for(const tab of ['build','owned','saved','account','upgrade']){$(tab+'Panel').hidden=tab!==name;$(tab+'Tab').setAttribute('aria-selected',String(tab===name));}if(name==='saved')renderSavedBuilds();if(name==='account'){renderAccountOverview();updateAccountSuggestions();}if(name==='upgrade')refreshUpgradeSources();}
function collectionChanged(){accountWorker?.terminate();accountWorker=null;accountRunningKey=null;accountResults=null;$('accountResults').innerHTML='';$('accountStatus').textContent='Inventory changed. Update suggestions to use the current collection.';if(!$('accountPanel').hidden)updateAccountSuggestions();}
function renderEquipmentInventory(){$('ownedArmorList').innerHTML=sortedOwnedEntries(ownedEquipment.armors,data.armor).map(({item:o,index:i})=>'<div class="ownedRow ownedEquipmentRow"><span class="ownedItemName">'+itemImage(o.id,'inventoryImage')+esc(data.armor.find(a=>a.id===o.id)?.name)+' <small>+'+o.level+'</small></span><button class="copy" data-remove-armor="'+i+'">Remove</button></div>').join('')||'<div class="empty">No owned armor yet.</div>';$('ownedContainerList').innerHTML=sortedOwnedEntries(ownedEquipment.containers,allContainers()).map(({item:id,index:i})=>'<div class="ownedRow ownedEquipmentRow"><span class="ownedItemName">'+itemImage(id,'inventoryImage')+esc(allContainers().find(c=>c.id===id)?.name)+'</span><button class="copy" data-remove-container="'+i+'">Remove</button></div>').join('')||'<div class="empty">No owned bags, containers or backpacks yet.</div>';$('ownedArmorTab').textContent='Armor ('+ownedEquipment.armors.length+')';$('ownedContainersTab').textContent='Bags & Containers ('+ownedEquipment.containers.length+')';}
function saveEquipment(){persistCollection('stalzone-equipment-v1',ownedEquipment);renderEquipmentInventory();collectionChanged();}
async function saveBuildCopy(build,configuration,existing=null){build=structuredClone(build);configuration=structuredClone(configuration);const name=await promptBuildName(existing?.name||inferBuildName(build,configuration),existing?'Save changes':'Save build');if(name===null)return null;const entry={id:existing?.id||crypto.randomUUID(),name,cfg:structuredClone(configuration),items:structuredClone(build.items),savedAt:existing?.savedAt||new Date().toISOString(),updatedAt:new Date().toISOString()};entry.cfg.includeNegativeSpeed=true;delete entry.cfg.market;delete entry.cfg.ownedInventory;const index=existing?savedBuilds.findIndex(b=>b.id===existing.id):-1;if(index>=0)savedBuilds[index]=entry;else savedBuilds.push(entry);const persisted=persistCollection('stalzone-saved-builds-v1',savedBuilds);renderSavedBuilds();$('savedStatus').textContent=persisted?'Build saved.':'Saved for this session only; browser storage is unavailable.';return entry;}
function savedEvaluation(entry){return evaluateEditedBuild(entry.items,{...entry.cfg,filters:{},market,ownedInventory:ownedInventory,omitOwned:true},data);}
function collectionCard(entry,actions=''){const r=savedEvaluation(entry),armor=data.armor.find(a=>a.id===entry.cfg.armor),container=allContainers().find(c=>c.id===entry.cfg.container);return`<article class="build"><div class="buildTop"><div><h3>${esc(entry.name)}</h3>${equipmentImages(entry.cfg)}<small class="collectionSlots">${entry.items.length} slots</small></div>${actions}</div><div class="metrics">${entry.healingFocus||entry.cfg.accountObjective==='healing'?'<div class="metric healingRateMetric"><b>'+f(healingPerSecond(r.s),3)+'<small>% / s</small></b><span>Healing per second</span></div>':''}${['ehp','bullet_dmg_factor','health_bonus','heal_efficiency','artefakt_heal','regeneration_bonus','speed','running_speed'].map(key=>`<div class="metric"><b>${f(r.s[key])}</b><span>${esc(filterStats.find(s=>s.key===key).name)}</span></div>`).join('')}<div class="metric"><b>${money(entry.upgradeCost??r.s.cost)}</b><span>${entry.upgradeCost!=null?'Investment':'Left to buy'}</span></div></div><div class="arts">${orderedArtifactEntries(entry.items).map(({item})=>`<div class="art" style="--rarity:${tiers[item.rarity].color}">${artifactCardIcon(item,entry.cfg.level)}<b style="color:${tiers[item.rarity].color}">${esc(data.artefact.find(a=>a.id===item.id)?.name)}</b><small>${esc(tiers[item.rarity].name)} · ${f(item.quality)}%</small><small>Bonuses: ${(item.bonusKeys||[]).map(k=>esc(data.names[k]||k)).join(', ')||'None'}</small></div>`).join('')}</div>${collectionBuildNotes(r,armor,container,entry.cfg)}</article>`;}
function renderSavedBuilds(){if($('upgradeSource'))refreshUpgradeSources();$('savedList').innerHTML=savedBuilds.map((entry,i)=>{try{return collectionCard(entry,`<div class="buildActions"><button class="copy" data-load-optimizer="${i}">Load into Optimizer</button><button class="copy" data-edit-saved="${i}">Upgrade Build</button><button class="copy" data-rename-saved="${i}">Rename</button><button class="copy" data-delete-saved="${i}">Delete</button></div>`);}catch(e){return`<p>${esc(entry.name)}: ${esc(e.message)}. <button data-delete-saved="${i}">Delete</button></p>`;}}).join('')||'<div class="empty">No saved builds yet. Use Save build on a search result or account suggestion.</div>';}
function draftFields(){const d=savedDraft;const select=(id,list,value)=>`<select id="${id}">${list.map(o=>`<option value="${esc(o.id)}" ${String(o.id)===String(value)?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`;const levels=Array.from({length:16},(_,i)=>({id:i,name:'+'+i}));$('savedEditorFields').innerHTML=`<label>Build name<input id="draftName" value="${esc(d.name)}"></label><label>Armor${select('draftArmor',[{id:'',name:'No armor'},...data.armor],d.cfg.armor)}</label><label>Armor upgrade${select('draftArmorLevel',levels,d.cfg.armorLevel)}</label><label>Bag / container / backpack${select('draftContainer',allContainers(),d.cfg.container)}</label>`+d.items.map((item,i)=>`<div class="ownedForm" data-draft-slot="${i}"><label>Artifact${select('draftArtifact'+i,data.artefact,item.id)}</label><label>Rarity${select('draftRarity'+i,tiers.filter(t=>t.available!==false),item.rarity)}</label><label>Quality %<input id="draftQuality${i}" type="number" step="any" min="${tiers[item.rarity].min}" max="${tiers[item.rarity].max}" value="${item.quality}" required></label><label>Upgrade${select('draftLevel'+i,levels,item.level)}</label><div>Bonuses${data.artefact.find(a=>a.id===item.id).bonus.map(b=>`<label class="checkrow"><input type="checkbox" data-draft-bonus="${i}" value="${b.k}" ${(item.bonusKeys||[]).includes(b.k)?'checked':''}>${esc(data.names[b.k])}</label>`).join('')}</div><button class="copy" data-remove-draft="${i}">Remove</button></div>`).join('');updateSavedDraft();}
function readSavedDraft(){const d=savedDraft;d.name=$('draftName').value.trim()||'Saved build';Object.assign(d.cfg,{armor:$('draftArmor').value,armorLevel:+$('draftArmorLevel').value,container:$('draftContainer').value,includeNegativeSpeed:true});for(let i=0;i<d.items.length;i++){const item=d.items[i];Object.assign(item,{id:$('draftArtifact'+i).value,rarity:+$('draftRarity'+i).value,quality:+$('draftQuality'+i).value,level:+$('draftLevel'+i).value,bonusKeys:[...$('savedEditorFields').querySelectorAll('[data-draft-bonus="'+i+'"]:checked')].map(e=>e.value)});}}
function updateSavedDraft(){try{readSavedDraft();if([...$('savedEditorFields').querySelectorAll('input')].some(input=>!input.checkValidity()))throw Error('Enter valid values for each artifact quality.');const d=savedDraft,capacity=allContainers().find(c=>c.id===d.cfg.container).levels[0].size;if(d.items.length>capacity)throw Error('Too many artifacts for this container ('+capacity+' slots).');for(const item of d.items){const a=data.artefact.find(a=>a.id===item.id),count=Math.floor(item.level/5)+(a.exbo==='9n7z'&&item.level>=1?1:0);if(item.bonusKeys.length>count)throw Error('Too many bonuses selected for '+a.name+' at this upgrade.');}const r=savedEvaluation(d);$('savedEditorSummary').textContent='EHP '+f(r.s.ehp)+' · Vitality '+f(r.s.health_bonus)+'% · Healing '+f(r.s.heal_efficiency)+'% · Movement Speed '+f(r.s.speed)+'% · Running Speed '+f(r.s.running_speed)+'% · Regeneration '+f(r.s.regeneration_bonus)+'% · Periodic Healing '+f(r.s.artefakt_heal)+'% · Left to buy '+money(r.s.cost)+' · '+(r.safe?'Within infection limits':'Warning: exceeds infection limits');$('savedEditorSave').disabled=false;}catch(e){$('savedEditorSummary').textContent=e.message;$('savedEditorSave').disabled=true;}if(typeof upgradeReady!=='undefined'&&upgradeReady)renderUpgradePreview();}
function updateAccountSuggestions(force=false){renderAccountOverview();const key=accountSuggestionKey();if(!force&&accountRunningKey===key)return;if(!force&&accountResults&&accountResultKey===key){renderAccountSuggestions();return;}let saved=null;if(!force)try{const cached=JSON.parse(localStorage.getItem('stalzone-account-cache-v2'));if(cached?.key===key)saved=cached;}catch{}if(saved?.done){accountResults=saved.result;accountResultKey=key;renderAccountSuggestions();return;}accountWorker?.terminate();accountWorker=null;accountRunningKey=null;if(!ownedEquipment.armors.length||!ownedEquipment.containers.length){$('accountResults').innerHTML='';$('accountStatus').textContent='Add at least one armor and one bag, container or backpack in Storage.';return;}if(saved?.result){accountResults=saved.result;renderAccountSuggestions();}else $('accountResults').innerHTML='';$('accountStatus').textContent='Checking owned equipment combinations…';const active=createSearchWorker();accountWorker=active;accountRunningKey=key;active.onmessage=e=>{if(accountWorker!==active)return;if(e.data.error){accountRunningKey=null;active.terminate();$('accountStatus').textContent=e.data.error;return;}if(e.data.partial||e.data.done){accountResults=e.data.done?e.data:e.data.partial;accountResultKey=key;try{localStorage.setItem('stalzone-account-cache-v2',JSON.stringify({key,result:accountResults,done:!!e.data.done}));}catch{}renderAccountSuggestions();}if(!e.data.done){$('accountStatus').textContent='Checking equipment '+e.data.depth+' / '+e.data.slots;return;}accountRunningKey=null;active.terminate();};active.onerror=()=>{accountRunningKey=null;active.terminate();$('accountStatus').textContent='Account search failed. Try Update suggestions.';};active.postMessage({mode:'account',data,inventory:structuredClone(ownedInventory),equipment:structuredClone(ownedEquipment),resume:saved?.result||null});}
