const backupKeys=['stalzone-player-lookup-v1','stalzone-upgrade-exclusions-v1','stalzone-priorities-v1','stalzone-owned-v1','stalzone-equipment-v1','stalzone-saved-builds-v1','stalzone-settings-v5','stalzone-settings-v3','stalzone-rarity-exclusions-v1','stalzone-exclusions-v1','stalzone-edits-v4','stalzone-results-order','stalzone-market-region','stalzone-auto-prices'];let pendingImport=null;
function storageFailure(){$('storageStatus').textContent='Browser storage is unavailable or full. Export saved data before closing to keep your changes.';}
function createBackup(){const values={};try{for(const key of backupKeys){const value=localStorage.getItem(key);if(value!==null)values[key]=value;}}catch{}values['stalzone-priorities-v1']=JSON.stringify(statPriorities);values['stalzone-owned-v1']=JSON.stringify(ownedInventory);values['stalzone-equipment-v1']=JSON.stringify(ownedEquipment);values['stalzone-saved-builds-v1']=JSON.stringify(savedBuilds);values['stalzone-rarity-exclusions-v1']=JSON.stringify(rarityExclusions);values['stalzone-settings-v5']=JSON.stringify(cfg());values['stalzone-results-order']=$('resultOrder').value;values['stalzone-market-region']=marketRegion;values['stalzone-auto-prices']=String($('autoPrices').checked);return{format:'stalzone-artifact-lab-backup',version:1,exportedAt:new Date().toISOString(),values};}
function validateBackup(backup){if(backup?.format!=='stalzone-artifact-lab-backup'||backup.version!==1||!backup.values||typeof backup.values!=='object'||Array.isArray(backup.values))throw Error('Choose a STALZONE Artifact Lab data export.');const values={};for(const key of backupKeys){if(!(key in backup.values))continue;const value=backup.values[key];if(typeof value!=='string')throw Error('Invalid backup entry: '+key);if(!['stalzone-results-order','stalzone-market-region','stalzone-auto-prices'].includes(key)){let parsed;try{parsed=JSON.parse(value);}catch{throw Error('Invalid backup entry: '+key);}if(['stalzone-owned-v1','stalzone-saved-builds-v1','stalzone-exclusions-v1'].includes(key)&&!Array.isArray(parsed))throw Error('Invalid collection in backup.');if(['stalzone-equipment-v1','stalzone-settings-v5','stalzone-rarity-exclusions-v1'].includes(key)&&(!parsed||typeof parsed!=='object'||Array.isArray(parsed)))throw Error('Invalid settings in backup.');if(key==='stalzone-equipment-v1'&&(!Array.isArray(parsed.armors)||!Array.isArray(parsed.containers)))throw Error('Invalid equipment collection.');if(key==='stalzone-saved-builds-v1'&&parsed.some(b=>!b||typeof b.name!=='string'||!b.cfg||!Array.isArray(b.items)))throw Error('Invalid saved build.');}values[key]=value;}if(!values['stalzone-owned-v1']||!values['stalzone-equipment-v1']||!values['stalzone-saved-builds-v1'])throw Error('The backup is missing its collections.');return values;}
function writeImportedBackup(values){const previous=new Map();try{for(const key of backupKeys)previous.set(key,localStorage.getItem(key));for(const key of backupKeys){if(key in values)localStorage.setItem(key,values[key]);else localStorage.removeItem(key);}return true;}catch(e){for(const [key,value]of previous){try{if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value);}catch{}}throw Error('Could not store the import. Browser storage may be blocked or full.');}}
$('exportData').onclick=()=>{try{const blob=new Blob([JSON.stringify(createBackup(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='STALZONE-saved-data-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);$('storageStatus').textContent='Data exported. Import this file in your other browser.';}catch(e){$('storageStatus').textContent='Export failed: '+e.message;}};
$('importData').onclick=()=>$('importDataFile').click();$('importDataFile').onchange=async()=>{try{const file=$('importDataFile').files[0];if(!file)return;if(file.size>20000000)throw Error('Backup file is too large.');pendingImport=validateBackup(JSON.parse(await file.text()));const owned=JSON.parse(pendingImport['stalzone-owned-v1']),equipment=JSON.parse(pendingImport['stalzone-equipment-v1']),builds=JSON.parse(pendingImport['stalzone-saved-builds-v1']);$('importPreviewText').textContent=owned.reduce((n,o)=>n+(Number(o.quantity)||0),0)+' artifact copies · '+equipment.armors.length+' armors · '+equipment.containers.length+' containers · '+builds.length+' saved builds';$('importPreview').showModal();}catch(e){pendingImport=null;$('storageStatus').textContent='Import failed: '+e.message;}finally{$('importDataFile').value='';}};
$('cancelImport').onclick=()=>{pendingImport=null;$('importPreview').close();};$('applyImport').onclick=()=>{if(!pendingImport)return;try{writeImportedBackup(pendingImport);location.reload();}catch(e){$('importPreviewText').textContent=e.message;}};
