let draggedPriority=null;
function renderPriorities(){$('priorityList').innerHTML=statPriorities.map((p,i)=>{const stat=priorityStats.find(s=>s.key===p.key);return '<div class="priorityRow '+(p.enabled?'':'ignored')+'" draggable="true" data-priority-key="'+p.key+'"><span aria-hidden="true">⠿</span><span class="priorityName">'+(i+1)+'. '+stat.name+'</span><button class="copy" data-priority-move="-1" data-priority-index="'+i+'" aria-label="Move '+stat.name+' up" '+(i===0?'disabled':'')+'>↑</button><button class="copy" data-priority-move="1" data-priority-index="'+i+'" aria-label="Move '+stat.name+' down" '+(i===statPriorities.length-1?'disabled':'')+'>↓</button><label><input type="checkbox" data-priority-ignore="'+p.key+'" '+(!p.enabled?'checked':'')+'> Ignore</label></div>';}).join('');}
function prioritiesChanged(){persistCollection('stalzone-priorities-v1',statPriorities);renderPriorities();dirty();}
$('priorityList').addEventListener('dragstart',e=>{if(e.target.closest('input,button,label')){e.preventDefault();return;}const row=e.target.closest('[data-priority-key]');if(!row)return;draggedPriority=row.dataset.priorityKey;e.dataTransfer.setData('text/plain',draggedPriority);e.dataTransfer.effectAllowed='move';});
$('priorityList').addEventListener('dragover',e=>{if(draggedPriority&&e.target.closest('[data-priority-key]')){e.preventDefault();e.dataTransfer.dropEffect='move';}});
$('priorityList').addEventListener('drop',e=>{e.preventDefault();const row=e.target.closest('[data-priority-key]');if(!row||!draggedPriority)return;const from=statPriorities.findIndex(p=>p.key===draggedPriority),to=statPriorities.findIndex(p=>p.key===row.dataset.priorityKey);draggedPriority=null;if(from<0||to<0||from===to)return;const [entry]=statPriorities.splice(from,1);statPriorities.splice(to,0,entry);prioritiesChanged();});
$('priorityList').addEventListener('dragend',()=>{draggedPriority=null;});$('priorityList').addEventListener('change',e=>{const key=e.target.dataset.priorityIgnore;if(!key)return;statPriorities.find(p=>p.key===key).enabled=!e.target.checked;prioritiesChanged();});$('priorityList').addEventListener('click',e=>{const button=e.target.closest('[data-priority-move]');if(!button)return;const from=+button.dataset.priorityIndex,to=from+(+button.dataset.priorityMove);if(to<0||to>=statPriorities.length)return;[statPriorities[from],statPriorities[to]]=[statPriorities[to],statPriorities[from]];prioritiesChanged();});renderPriorities();

