function renderUpgradePreview(){if(!savedDraft)return;const d=savedDraft;for(const id of ['draftArmor','draftContainer',...d.items.map((_,i)=>'draftArtifact'+i)])syncItemSelect($(id));upgradeSelection=Math.max(0,Math.min(upgradeSelection,d.items.length-1));$('upgradeSlots').innerHTML=orderedArtifactEntries(d.items).map(({item,index:i})=>{const a=data.artefact.find(a=>a.id===item.id),tier=tiers[item.rarity];return '<button class="upgradeSlot '+(i===upgradeSelection?'selected':'')+'" style="--rarity:'+tier.color+'" data-upgrade-slot="'+i+'">'+itemImage(item.id,'slotImage')+'<b>'+esc(a?.name)+'</b><span>+'+item.level+' · '+f(item.quality)+'%</span></button>';}).join('')||'<p class="hint">Use Add artifact to start assembling a build.</p>';const selected=d.items[upgradeSelection];if(selected){const a=data.artefact.find(a=>a.id===selected.id),values=artifactStats(a,selected.level,selected.quality,selected.bonusKeys,selected.rarity);$('upgradeArtifactStats').innerHTML='<div class="selectedArtifactHeading">'+itemImage(a.id,'selectedItemImage')+'<h3 style="color:'+tiers[selected.rarity].color+'">'+esc(a.name)+'</h3></div>'+Object.entries(values).filter(([key])=>data.names[key]).map(([key,value])=>'<div class="upgradeStat"><span>'+esc(data.names[key])+'</span><b class="'+((infections.includes(key)?value>0:value<0)?'negative':'positive')+'">'+f(value)+'</b></div>').join('');}else $('upgradeArtifactStats').innerHTML='';$('savedEditorFields').querySelectorAll('[data-draft-slot]').forEach((row,i)=>{row.hidden=i!==upgradeSelection;const tier=tiers[d.items[i].rarity];row.style.borderColor=tier.color;});try{const r=savedEvaluation(d);const groups=[['Survivability',['ehp','health_bonus','heal_efficiency','regeneration_bonus','artefakt_heal']],['Mobility',['speed','running_speed','stamina_bonus','stamina_regeneration_bonus','max_weight_bonus']],['Protection',['bullet_dmg_factor','tear_dmg_factor','stopping_protection','explosion_dmg_factor']],['Accumulation',infections]];$('upgradeStats').innerHTML=groups.map(([title,keys])=>'<h4>'+title+'</h4>'+keys.map(key=>{const value=r.s[key]||0,cap=infections.includes(key)?(infections.indexOf(key)<4?10:infections.indexOf(key)===4?20:0):null,bad=cap!==null?value>cap:value<0;return '<div class="upgradeStat"><span>'+esc(filterStats.find(s=>s.key===key)?.name||data.names[key]||key)+'</span><b class="'+(bad?'negative':'positive')+'">'+f(value)+(cap!==null?' / '+cap:'')+'</b></div>';}).join('')).join('')+'<p class="hint">'+(r.safe?'Within infection limits':'Exceeds infection limits')+'</p>';}catch(e){$('upgradeStats').textContent=e.message;}}
