function renderUpgradeExclusions(){$('upgradeExcludeArtifact').innerHTML='<option value="">Choose an artifact…</option>'+data.artefact.filter(a=>!upgradeExcluded.includes(a.id)).map(a=>'<option value="'+esc(a.id)+'">'+esc(a.name)+'</option>').join('');$('upgradeExcludedList').innerHTML=upgradeExcluded.map(id=>'<button class="copy" data-allow-upgrade="'+esc(id)+'">'+esc(data.artefact.find(a=>a.id===id).name)+' ×</button>').join('');syncItemSelect($('upgradeExcludeArtifact'));}
function changeUpgradeExclusions(){persistCollection('stalzone-upgrade-exclusions-v1',upgradeExcluded);upgradeWorker?.terminate();$('upgradeResults').innerHTML='';upgradeSuggestions=[];renderUpgradeExclusions();$('upgradeStatus').textContent='Exclusions updated. Find upgrades to apply them. Current build artifacts are unchanged.';}
$('upgradeExcludeAdd').onclick=()=>{const id=$('upgradeExcludeArtifact').value;if(id&&!upgradeExcluded.includes(id)){upgradeExcluded.push(id);changeUpgradeExclusions();}};$('upgradeExcludedList').onclick=e=>{const id=e.target.closest('[data-allow-upgrade]')?.dataset.allowUpgrade;if(id){upgradeExcluded=upgradeExcluded.filter(x=>x!==id);changeUpgradeExclusions();}};renderUpgradeExclusions();

function upgradeItemChanges(before,after){const token=i=>JSON.stringify([i.id,i.rarity,i.quality,i.level,[...(i.bonusKeys||[])].sort()]),remaining=after.slice(),removed=[],kept=[];for(const old of before){const index=remaining.findIndex(i=>token(i)===token(old));if(index>=0){kept.push(old);remaining.splice(index,1);}else removed.push(old);}const changes=[];for(let i=removed.length-1;i>=0;i--){const index=remaining.findIndex(n=>n.id===removed[i].id);if(index>=0){changes.unshift({kind:'change',from:removed[i],to:remaining[index]});removed.splice(i,1);remaining.splice(index,1);}}while(removed.length&&remaining.length)changes.push({kind:'replace',from:removed.shift(),to:remaining.shift()});for(const item of removed)changes.push({kind:'remove',from:item});for(const item of remaining)changes.push({kind:'add',to:item});return{kept,changes};}
function upgradeChangeSummary(before,after){const diff=upgradeItemChanges(before,after),name=i=>data.artefact.find(a=>a.id===i.id)?.name||i.id,label=i=>itemImage(i.id,'comparisonImage')+esc(name(i))+' <span style="color:'+tiers[i.rarity].color+'">'+esc(tiers[i.rarity].name)+' · '+f(i.quality)+'% · +'+i.level+'</span>';const lines=diff.changes.map(change=>{let text=change.kind==='replace'?'Replace '+label(change.from)+' → '+label(change.to):change.kind==='change'?'Change '+label(change.from)+' → '+label(change.to):change.kind==='add'?'Add '+label(change.to):'Remove '+label(change.from);if(change.from&&change.to&&JSON.stringify([...(change.from.bonusKeys||[])].sort())!==JSON.stringify([...(change.to.bonusKeys||[])].sort()))text+='<small>Bonuses: '+(change.from.bonusKeys||[]).map(k=>esc(data.names[k]||k)).join(', ')+' → '+((change.to.bonusKeys||[]).map(k=>esc(data.names[k]||k)).join(', ')||'None')+'</small>';return '<li>'+text+'</li>';});const kept=new Map();for(const {item} of orderedArtifactEntries(diff.kept))kept.set(name(item),(kept.get(name(item))||0)+1);return '<div class="upgradeChangeSummary"><h3>Artifact changes</h3><ul>'+lines.join('')+'</ul>'+(kept.size?'<div class="hint">Kept: '+[...kept].map(([name,count])=>(count>1?count+' × ':'')+esc(name)).join(', ')+'</div>':'')+'</div>';}

function selectOwnedCategory(category,focus=false){const names={artifacts:'Artifacts',armor:'Armor',containers:'Containers'};if(!names[category])return;for(const[key,name]of Object.entries(names)){const button=$('owned'+name+'Tab'),active=key===category;$('owned'+name+'Panel').hidden=!active;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;if(active&&focus)button.focus();}}
$('ownedCategoryTabs').onclick=e=>{const button=e.target.closest('[data-owned-category]');if(button)selectOwnedCategory(button.dataset.ownedCategory);};$('ownedCategoryTabs').onkeydown=e=>{const categories=['artifacts','armor','containers'],button=e.target.closest('[data-owned-category]');if(!button)return;let index=categories.indexOf(button.dataset.ownedCategory);if(e.key==='ArrowRight')index=(index+1)%3;else if(e.key==='ArrowLeft')index=(index+2)%3;else if(e.key==='Home')index=0;else if(e.key==='End')index=2;else return;e.preventDefault();selectOwnedCategory(categories[index],true);};selectOwnedCategory('artifacts');

function sortedOwnedEntries(items,catalog){const names=new Map(catalog.map(item=>[item.id,item.name]));return items.map((item,index)=>({item,index})).sort((a,b)=>String(names.get(typeof a.item==='string'?a.item:a.item.id)||'').localeCompare(String(names.get(typeof b.item==='string'?b.item:b.item.id)||''),'en',{sensitivity:'base',numeric:true})||((a.item.rarity??0)-(b.item.rarity??0))||((a.item.level??0)-(b.item.level??0))||((a.item.quality??0)-(b.item.quality??0))||a.index-b.index);}

function inferBuildName(build,configuration){let raw={};try{raw=evaluateEditedBuild(build.items,{...configuration,filters:{},market},data).raw;}catch{}const features=[['Bullet resistance','bullet_dmg_factor',45],['Vitality','health_bonus',5],['Healing','heal_efficiency',15],['Regeneration','regeneration_bonus',3],['Periodic Healing','artefakt_heal',.8],['Movement Speed','speed_modifier',3],['Running Speed','sprint_speed_modifier',3],['Carry','max_weight_bonus',20],['Stamina','stamina_bonus',70]].map(([name,key,scale])=>({name,score:(raw[key]||0)/scale})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);const theme=features.slice(0,2).map(x=>x.name).join(' & ')||'Equipment';const container=allContainers().find(c=>c.id===configuration.container)?.name;return (theme+(container?' · '+container:'')).slice(0,100);}
