function accountSuggestionKey(){const text=JSON.stringify({model:12,data,inventory:ownedInventory,equipment:ownedEquipment});let h=2166136261;for(let i=0;i<text.length;i++)h=Math.imul(h^text.charCodeAt(i),16777619);return h.toString(16)+':'+text.length;}
function renderAccountSuggestions(){const value=accountResults;if(!value)return;$('accountStatus').textContent=value.complete?'Suggestions ready.':'Best suggestions found so far.';$('accountResults').innerHTML=['regular','speed','healing'].map(kind=>{const entry=value[kind];return entry?collectionCard({cfg:entry.cfg,items:entry.build.items,name:kind==='regular'?'Regular Build':kind==='healing'?'Healing Build':'Movement Speed Build'},'<button class="copy" data-save-account="'+kind+'">Save build</button>'):'<p>No full '+kind+' build found using only artifacts in Storage.</p>';}).join('');}
function accountInventoryValue(){let copies=0,priced=0,subtotal=0;for(const item of ownedInventory){const quantity=Math.max(0,Math.floor(Number(item.quantity)||0));copies+=quantity;const art=data.artefact.find(a=>a.id===item.id),quote=priceQuote(market,art?.exbo,item.rarity,item.level);if(quote.price!=null){priced+=quantity;subtotal+=quote.price*quantity;}}return{copies,priced,subtotal,total:copies===priced?subtotal:null};}
function renderAccountOverview(){const value=accountInventoryValue();const cards=[['Artifacts owned',f(value.copies,0)],['Armor owned',f(ownedEquipment.armors.length,0)],['Bags & containers',f(ownedEquipment.containers.length,0)],['Saved builds',f(savedBuilds.length,0)],['Artifact value · '+marketRegion,money(value.subtotal)+(value.priced<value.copies?' · partial':'')]];$('accountOverview').innerHTML=cards.map(([label,value])=>'<div class="accountSummaryCard"><span>'+esc(label)+'</span><b>'+esc(value)+'</b></div>').join('')+'<p class="hint">'+value.priced+' / '+value.copies+' owned copies priced'+(value.priced<value.copies?' · Partial estimate; unpriced copies are not included.':'')+' · Rarity and upgrade matched; exact quality and bonus rolls may affect value.</p>';}
function formatPlayerValue(value,type){if(type==='DATE'){const date=new Date(value);return Number.isNaN(date.getTime())?null:date.toLocaleString('en-CA',{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});}const n=Number(value);if(!Number.isFinite(n))return null;if(type==='DURATION'){const minutes=Math.floor(Math.max(0,n)/60000),hours=Math.floor(minutes/60);return f(hours,0)+'h '+(minutes%60)+'m';}if(type==='INTEGER')return f(n,0);if(type==='DECIMAL')return f(n,2);return null;}
function profileRows(profile){const rows=[],add=(label,value,category='Overview')=>{if(value!=null&&value!=='')rows.push([label,String(value),category]);};const factions={merc:'Mercenaries',stalker:'Stalkers',bandit:'Bandits',duty:'Duty',freedom:'Freedom',covenant:'Covenant',frontier:'Frontier',rise:'Rise'};add('Player Name',profile.username||profile.name);add('Faction',factions[profile.alliance||profile.faction]);add('Clan',typeof profile.clan==='string'?profile.clan:profile.clan?.name);if(profile.lastLogin)add('Last Login',formatPlayerValue(profile.lastLogin,'DATE'));const main=new Set(['kil','dea','ast','pla-tim','reg-tim','art-col','npc-kil','mut-kil','que-fin','ach-points','max-mon-amo']);for(const definition of data.playerStats||[]){const stat=profile.stats?.find(s=>s.id===definition.id);if(!stat)continue;const value=formatPlayerValue(stat.value,definition.type);add(definition.name,value,main.has(definition.id)?'Overview':definition.category||'Other');}return rows;}
function renderPlayerProfile(profile,region,cached=false,savedAt=null){const logoKey=({mercenaries:'merc',mercenary:'merc',zarya:'rise',zavet:'covenant'})[profile.alliance||profile.faction]||(profile.alliance||profile.faction),logo=data.factionLogos?.[logoKey];const rows=profileRows(profile),name=profile.username||profile.name||'Player',faction=rows.find(r=>r[0]==='Faction')?.[1],clan=rows.find(r=>r[0]==='Clan')?.[1],stat=id=>profile.stats?.find(s=>s.id===id)?.value,definition=id=>data.playerStats?.find(s=>s.id===id),featured=['kil','pla-tim','art-col'],featuredLabels=new Set(featured.map(id=>definition(id)?.name)),cards=featured.filter(id=>stat(id)!=null&&definition(id)).map(id=>({label:definition(id).name,value:formatPlayerValue(stat(id),definition(id).type),tone:id==='kil'?'ember':id==='art-col'?'violet':'teal'}));if(Number.isFinite(Number(stat('kil')))&&Number(stat('dea'))>0)cards.splice(1,0,{label:'Kill / death ratio',value:f(Number(stat('kil'))/Number(stat('dea')),2),tone:'amber'});const markup=items=>'<div class="profileStats">'+items.map(([label,value])=>'<div class="upgradeStat"><span>'+esc(label)+'</span><b>'+esc(value)+'</b></div>').join('')+'</div>',categories=[...new Set(rows.map(row=>row[2]).filter(c=>c!=='Overview'))],overview=rows.filter(row=>row[2]==='Overview'&&!['Player Name','Faction','Clan'].includes(row[0])&&!featuredLabels.has(row[0]));$('playerProfile').innerHTML='<div class="playerHero">'+(logo?'<div class="playerFactionEmblem"><img src="'+esc(logo)+'" alt="'+esc((faction||'Sub-faction')+' emblem')+'"></div>':'')+'<div class="playerIdentity"><div class="playerBadges"><span>'+esc(region)+'</span>'+'</div><p class="playerNameLabel">Player Name</p><h3>'+esc(name)+'</h3>'+(clan?'<p class="playerClan">'+esc(clan)+'</p>':'')+'</div><div class="playerHeroDecoration" aria-hidden="true"><i></i><i></i><i></i></div></div><div class="playerHighlights">'+cards.map(card=>'<div class="playerHighlight '+card.tone+'"><span>'+esc(card.label)+'</span><b>'+esc(card.value)+'</b></div>').join('')+'</div><section class="playerOverview"><h4>At a glance</h4>'+markup(overview)+'</section><div class="playerDetails">'+categories.map(category=>{const items=rows.filter(row=>row[2]===category);return '<details class="playerStatGroup"><summary><span>'+esc(category.toLowerCase().replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()))+'</span><small>'+items.length+' stats</small></summary>'+markup(items)+'</details>';}).join('')+'</div>';$('playerLookupStatus').textContent=region+' · '+(cached?'Saved profile':'Public profile')+(savedAt?' · Updated '+formatPlayerValue(savedAt,'DATE'):'');}
function restorePlayerLookup(){try{const saved=JSON.parse(localStorage.getItem('stalzone-player-lookup-v1')||'null');if(!saved||typeof saved.name!=='string'||!['NA','EU','SEA','RU'].includes(saved.region))return;$('playerName').value=saved.name;$('playerRegion').value=saved.region;if(saved.profile&&typeof saved.profile==='object')renderPlayerProfile(saved.profile,saved.region,true,saved.savedAt);}catch{}}
$('playerLookupForm').onsubmit=async e=>{e.preventDefault();const name=$('playerName').value.trim(),region=$('playerRegion').value;if(!name)return;$('playerLookupButton').disabled=true;$('playerLookupStatus').textContent='Looking up player…';try{const response=await fetch(auctionBase()+'/api/player?region='+encodeURIComponent(region)+'&name='+encodeURIComponent(name),{signal:AbortSignal.timeout(25000)});const body=await response.json();if(!response.ok)throw Error(body.error||'Player lookup unavailable.');const savedAt=new Date().toISOString(),record={name:body.profile.username||body.profile.name||name,region,profile:body.profile,savedAt};$('playerName').value=record.name;try{localStorage.setItem('stalzone-player-lookup-v1',JSON.stringify(record));}catch{}renderPlayerProfile(body.profile,region,!!body.cached,savedAt);}catch(err){$('playerLookupStatus').textContent=err instanceof TypeError?'Start the live service to use player lookup.':err.message;}finally{$('playerLookupButton').disabled=false;}};
