function buildRequirementHelp(key){return ({ehp:'Bullet effective health, combining bullet resistance and vitality.',bullet_dmg_factor:'Bullet resistance from artifacts after container effectiveness, plus any storage bonus. Armor bullet resistance is excluded from these limits but still counts toward EHP.',heal_efficiency:'Total healing effectiveness bonus.',health_bonus:'Total vitality bonus used in the EHP calculation.',speed:'Movement Speed bonus from equipment and artifacts. Separate from Running Speed.',running_speed:'Running Speed (sprint) bonus from equipment and artifacts, including container effectiveness. Calculated separately from Movement Speed; the two bonuses are not added together.',regeneration_bonus:'Total health regeneration bonus. Separate from Periodic Healing.',artefakt_heal:'Periodic Healing percentage provided by artifacts, after container effectiveness. Separate from Health Regeneration and Healing Effectiveness.',stamina_bonus:'Extra stamina as a percentage, not stamina recovery.',max_weight_bonus:'Extra carrying capacity from equipment and artifacts, excluding the character’s base capacity.',cost:'Set your spending range in ₽ for artifacts still to purchase after any Storage credit. Use Maximum for your available budget; Minimum is optional. Armor, bags and upgrade materials are excluded.'})[key]||'';}

async function screenshotVariation(button){const card=button.closest('.build');if(!card)return;const original='Screenshot';button.disabled=true;button.textContent='Creating image…';let host,imagePromise;try{if(typeof window.html2canvas!=='function')throw Error('Screenshot tool unavailable. Reload the app.');if(!navigator.clipboard?.write||typeof ClipboardItem!=='function')throw Error('Image clipboard access is unavailable in this browser. Open the app through the local live service.');imagePromise=(async()=>{await document.fonts.ready;host=document.createElement('div');host.className='buildScreenshotHost';host.style.cssText='position:fixed;left:-20000px;top:0;width:1400px;padding:22px;background:#0b1211;z-index:-1;';const clone=card.cloneNode(true);clone.querySelectorAll('.buildActions,.excludeFromCard').forEach(el=>el.remove());clone.querySelectorAll('img').forEach(img=>img.loading='eager');clone.querySelectorAll('details').forEach(details=>details.open=true);clone.style.margin='0';const brand=document.createElement('div');brand.textContent='STALZONE LABS';brand.style.cssText='font:700 18px Arial;color:#efb65d;margin-bottom:14px;letter-spacing:2px;';host.append(brand,clone);document.body.append(host);normalizeScreenshotColors(host);await Promise.all([...clone.querySelectorAll('img')].map(img=>img.decode?.().catch(()=>{})));const canvas=await window.html2canvas(host,{backgroundColor:'#0b1211',scale:1.5,logging:false,useCORS:true,windowWidth:1480,scrollX:0,scrollY:0});const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Could not create the image.');return blob;})();await navigator.clipboard.write([new ClipboardItem({'image/png':imagePromise})]);button.textContent='Copied';}catch(error){button.textContent=original;$('progress').textContent=error.message;}finally{if(imagePromise)await imagePromise.catch(()=>{});host?.remove();button.disabled=false;if(button.textContent==='Creating image…')button.textContent=original;}}

function normalizeScreenshotColors(host){const canvas=document.createElement('canvas');canvas.width=canvas.height=1;const context=canvas.getContext('2d',{willReadFrequently:true});const rgba=value=>{context.clearRect(0,0,1,1);context.fillStyle=value;context.fillRect(0,0,1,1);const [r,g,b,a]=context.getImageData(0,0,1,1).data;return 'rgba('+r+','+g+','+b+','+(a/255)+')';};for(const element of [host,...host.querySelectorAll('*')]){const style=getComputedStyle(element);for(const key of ['color','backgroundColor','borderTopColor','borderRightColor','borderBottomColor','borderLeftColor'])if(/color\(|color-mix|oklch|oklab/.test(style[key]))element.style[key]=rgba(style[key]);if(/color\(|color-mix|oklch|oklab/.test(style.backgroundImage))element.style.backgroundImage='none';}}

