function renderUpgradeSuggestions(){$('upgradeResults').innerHTML=orderedUpgradeSuggestions().map((entry)=>{const i=upgradeSuggestions.indexOf(entry);return '<div class="upgradeComparison">'+collectionCard(entry,'<div class="buildActions"><button class="copy" data-adopt-upgrade="'+i+'">Use as current build</button><button class="copy" data-save-upgrade="'+i+'">Save build</button></div>')+'<section class="upgradeDifferenceSection"><h3>Stat changes</h3><div class="upgradeDeltas">'+['ehp','bullet_dmg_factor','health_bonus','heal_efficiency','regeneration_bonus','artefakt_heal','speed','running_speed','stamina_bonus','max_weight_bonus'].map(key=>{const r=savedEvaluation(entry),change=(r.s[key]||0)-(entry.baseline.s[key]||0);return '<span><span class="deltaLabel">'+esc(filterStats.find(s=>s.key===key)?.name||key)+'</span><b class="'+(change<0?'negative':'positive')+'">'+(change>0?'+':'')+f(change)+'</b></span>';}).join('')+'</div></section>'+upgradeChangeSummary(entry.baseline.items,entry.items)+'</div>';}).join('');}
