function artifactCardIcon(item,fallbackLevel=15){const level=item.level??fallbackLevel??15;return '<div class="artifactVisual"><span class="artifactUpgradeBadge" aria-label="Upgrade level +'+level+'">+'+level+'</span>'+itemImage(item.id,'artifactImage')+'</div>';}


function orderedArtifactEntries(items){const hazards=new Set(['radiation_accumulation','thermal_accumulation','biological_accumulation','psycho_accumulation']),catalog=new Map(data.artefact.map(a=>[a.id,a])),groups=new Map();items.forEach((item,index)=>{if(!groups.has(item.id)){const artifact=catalog.get(item.id);groups.set(item.id,{id:item.id,first:index,atom:artifact?.name==='Atom',offset:isDedicatedOffsetArtifact(artifact),rarity:item.rarity??3,entries:[]});}const group=groups.get(item.id);group.rarity=Math.max(group.rarity,item.rarity??3);group.entries.push({item,index});});return [...groups.values()].sort((a,b)=>Number(b.atom)-Number(a.atom)||Number(b.offset)-Number(a.offset)||b.rarity-a.rarity||a.first-b.first).flatMap(group=>group.entries.sort((a,b)=>(b.item.rarity??3)-(a.item.rarity??3)||(b.item.level??0)-(a.item.level??0)||(b.item.quality??0)-(a.item.quality??0)||a.index-b.index));}

function applyGearRarityColors(select){if(!['armor','container','inventoryArmor','inventoryContainer','draftArmor','draftContainer'].includes(select.id))return;const colors={DEFAULT:'#dce4dd',RANK_NEWBIE:'#9cd385',RANK_STALKER:'#8cbff2',RANK_VETERAN:'#ec91cb',RANK_MASTER:'#ed8e82',RANK_LEGEND:'#e1c77f'},catalog=new Map([...data.armor,...data.containers,...data.backpacks].map(item=>[item.id,item]));for(const option of Array.from(select.options)){if(!gearAllowedInPicker(catalog.get(option.value))){option.remove();continue;}option.style.color=colors[catalog.get(option.value)?.color]||colors.DEFAULT;option.style.backgroundColor='#101914';}select.style.color=colors[catalog.get(select.value)?.color]||colors.DEFAULT;if(select.ownerDocument)renderGearPicker(select);}

function isDedicatedOffsetArtifact(artifact){const core=new Set(['radiation_accumulation','thermal_accumulation','biological_accumulation','psycho_accumulation']),values=(artifact?.base||[]).filter(v=>v.k.endsWith('_accumulation')),reductions=values.filter(v=>core.has(v.k)&&Math.min(v.min??0,v.max??0)<0).length,addsHazard=values.some(v=>Math.max(v.min??0,v.max??0)>0);return reductions>=2||(reductions>0&&!addsHazard);}

