function gearColor(item){return ({DEFAULT:'#dce4dd',RANK_NEWBIE:'#9cd385',RANK_STALKER:'#8cbff2',RANK_VETERAN:'#ec91cb',RANK_MASTER:'#ed8e82',RANK_LEGEND:'#e1c77f'})[item?.color]||'#dce4dd';}
function renderGearPicker(select){
 let picker=select.previousElementSibling;
 if(!picker?.classList.contains('gearPicker')){
  picker=document.createElement('details');picker.className='gearPicker';
  select.before(picker);select.hidden=true;
 }
 const catalog=new Map([...data.armor,...allContainers()].map(item=>[item.id,item]));
 const selected=select.options[select.selectedIndex];
 picker.innerHTML='<summary style="color:'+gearColor(catalog.get(select.value))+'">'+esc(selected?.textContent||'Choose equipment…')+'</summary><div class="gearPickerMenu" role="listbox" aria-label="'+esc(select.getAttribute('aria-label')||'Equipment')+'">'+Array.from(select.options).map(option=>'<button type="button" role="option" aria-selected="'+option.selected+'" data-value="'+esc(option.value)+'" style="color:'+gearColor(catalog.get(option.value))+'">'+esc(option.textContent)+'</button>').join('')+'</div>';
 picker.querySelectorAll('[data-value]').forEach(button=>button.onclick=()=>{select.value=button.dataset.value;picker.open=false;select.dispatchEvent(new Event('change',{bubbles:true}));picker.querySelector('summary').focus();});
 picker.onkeydown=event=>{
  if(event.key==='Escape'){picker.open=false;picker.querySelector('summary').focus();}
  if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){
   event.preventDefault();picker.open=true;const buttons=[...picker.querySelectorAll('button')],index=buttons.indexOf(document.activeElement);
   const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:Math.max(0,Math.min(buttons.length-1,index+(event.key==='ArrowDown'?1:-1)));
   buttons[next]?.focus();
  }
 };
 picker.ontoggle=()=>{if(picker.open){document.querySelectorAll('.gearPicker[open]').forEach(other=>{if(other!==picker)other.open=false;});picker.querySelector('[aria-selected="true"]')?.scrollIntoView({block:'nearest'});}};
}
document.addEventListener('click',event=>document.querySelectorAll('.gearPicker[open]').forEach(picker=>{if(!picker.contains(event.target))picker.open=false;}));

function gearAllowedInPicker(item){return !item||!['DEFAULT','RANK_NEWBIE','RANK_STALKER'].includes(item.color);}
function updateMarketRegionButtons(){document.querySelectorAll('[data-market-region]').forEach(button=>{const active=button.dataset.marketRegion===$('marketRegion').value;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});}
function setupMarketRegionButtons(){
 const select=$('marketRegion');select.hidden=true;
 const group=document.createElement('div');group.className='marketRegionButtons';group.setAttribute('role','group');group.setAttribute('aria-label','Market region');
 group.innerHTML=['EU','NA','RU','SEA'].map(region=>'<button type="button" data-market-region="'+region+'">'+region+'</button>').join('');select.after(group);
 group.querySelectorAll('button').forEach(button=>button.onclick=()=>{if(select.value===button.dataset.marketRegion)return;select.value=button.dataset.marketRegion;select.dispatchEvent(new Event('change',{bubbles:true}));});
 select.addEventListener('change',updateMarketRegionButtons);updateMarketRegionButtons();
}
setupMarketRegionButtons();

