function hasFinderStatTargets(filters){return Object.entries(filters).some(([key,range])=>key!=='cost'&&(range.min!=null||range.max!=null));}
function renderGettingStarted(){
 $('progress').textContent='';$('results').classList.remove('stale');$('resultOrder').closest('.resultSort').hidden=true;
 $('results').innerHTML=`<section class="finderWelcome" aria-labelledby="finderWelcomeTitle">
 <div class="welcomeIntro"><span class="welcomeEyebrow">BUILD OPTIMIZER</span><h2 id="finderWelcomeTitle">Getting Started</h2><p>Choose your gear. Set your targets. Find a build that fits.</p></div>
 <ol class="welcomeSteps">
 <li><span class="welcomeStepNumber">01</span><div><h3>Choose your equipment</h3><p>Select your armor, its upgrade level, and your bag or container on the left.</p></div></li>
 <li><span class="welcomeStepNumber">02</span><div><h3>Set your wallet &amp; stat targets</h3><p>Enter a budget and at least one stat requirement. Leave other limits blank. Use the circled ? icons for help.</p></div></li>
 <li><span class="welcomeStepNumber">03</span><div><h3>Fine-tune your search</h3><p>Rank your stat priorities, restrict artifacts you don’t want, and choose whether stored artifacts reduce the purchase cost.</p></div></li>
 <li><span class="welcomeStepNumber">04</span><div><h3>Find matching builds</h3><p>Click <strong>Find matching builds</strong> below the filters. Compare variations, save a favorite, or open it in Upgrade Build.</p></div></li>
 </ol><div class="welcomeFooter">Already have a collection? Add it in <strong>Storage</strong>, or use <strong>Import data</strong> to restore your backup.</div>
 </section>`;
}

function collectionBuildNotes(r){
 const entries=infections.filter(key=>Math.abs(r.s[key]||0)>=0.0005);
 return '<section class="collectionInfections" aria-label="Infection levels"><div class="infectionSectionHeading"><h4>Infection levels</h4><span class="'+(r.safe?'positive':'negative')+'">'+(r.safe?'✓ Within infection limits':'Exceeds infection limits')+'</span></div>'+(entries.length?'<div class="metrics">'+entries.map(key=>'<div class="metric"><b>'+f(r.s[key],3)+'</b><span>'+esc(data.names[key])+'</span></div>').join('')+'</div>':'')+'</section>';
}

function equipmentStatSummary(stats){
 const percentages=new Set(['health_bonus','heal_efficiency','artefakt_heal','regeneration_bonus','speed_modifier','sprint_speed_modifier','stamina_bonus','stamina_regeneration_bonus','stopping_protection','bleeding_protection','effectiveness','inner_protection']);
 const labels={size:'Slots',effectiveness:'Effectiveness',inner_protection:'Infection protection',bullet_dmg_factor:'Bullet resistance',max_weight_bonus:'Carry weight'};
 const priority=['size','effectiveness','inner_protection','bullet_dmg_factor','health_bonus','heal_efficiency','artefakt_heal','regeneration_bonus','speed_modifier','sprint_speed_modifier','stamina_bonus','stamina_regeneration_bonus','max_weight_bonus'];
 const hidden=new Set(['tear_dmg_factor','explosion_dmg_factor','electra_dmg_factor','burn_dmg_factor','chemical_burn_dmg_factor','radiation_protection','thermal_protection','biological_protection','psycho_protection']);
 return '<div class="equipmentStatGrid">'+Object.entries(stats).filter(([key,value])=>!hidden.has(key)&&typeof value==='number'&&Number.isFinite(value)&&Math.abs(value)>=0.005).sort(([a],[b])=>{const ai=priority.indexOf(a),bi=priority.indexOf(b);return(ai<0?999:ai)-(bi<0?999:bi);}).map(([key,value])=>'<span><span>'+esc(labels[key]||data.names[key]||key.replaceAll('_',' '))+'</span><b>'+f(value)+(percentages.has(key)?'%':key==='max_weight_bonus'?' kg':'')+'</b></span>').join('')+'</div>';
}

