function optimizerTargetsFromSaved(entry){
 const evaluated=savedEvaluation(entry),targets={};
 for(const stat of filterStats){
  if(stat.key==='cost')continue;
  const value=stat.key==='bullet_dmg_factor'?evaluated.s.container_bullet_resistance:evaluated.s[stat.key]??0;
  if(!Number.isFinite(value))throw Error('This saved build has an invalid '+stat.name+' value.');
  // Round down to display precision so rounding never puts the saved build below its own minimum.
  targets[stat.key]=Math.floor((value+1e-10)*100)/100;
 }
 return targets;
}
function loadSavedBuildIntoOptimizer(entry){
 if(!entry?.cfg)throw Error('This saved build is missing its equipment settings.');
 const armor=data.armor.find(item=>item.id===entry.cfg.armor),container=allContainers().find(item=>item.id===entry.cfg.container);
 if(entry.cfg.armor&&!armor||!container||armor&&!armor.levels[entry.cfg.armorLevel])throw Error('This saved build uses equipment that is no longer available.');
 if(!gearAllowedInPicker(armor)||!gearAllowedInPicker(container))throw Error('This saved build uses a gear rarity that is excluded from the optimizer.');
 if(armor&&armor.compat?.[container.cat]&&armor.compat[container.cat]!=='Any'&&armor.compat[container.cat]!==container.name)throw Error('The saved armor and storage are incompatible.');
 const targets=optimizerTargetsFromSaved(entry);
 worker?.terminate();worker=null;setSearchLoading(false);$('run').disabled=false;
 $('armorSearch').value='';options($('armor'),armorOptions(),entry.cfg.armor||'');$('armorLevel').value=String(entry.cfg.armorLevel??15);equipment();
 $('container').value=entry.cfg.container;syncItemSelect($('container'));containerInfo();
 for(const [key,value] of Object.entries(targets)){const minimum=$(key+'Min'),maximum=$(key+'Max');minimum.value=f(value);maximum.value='';minimum.setCustomValidity('');maximum.setCustomValidity('');}
 currentCfg=null;resultMarket=null;results=[];displayResults=[];editing=null;
 selectWorkspace('build');renderGettingStarted();
 $('progress').textContent='Loaded '+entry.name+' · Review your targets and click Find matching builds.';
 try{localStorage.setItem(storageKey,JSON.stringify(cfg()));}catch{}
 $('buildTab').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});
}
